#include "dsky_nv_consumer_check.h"
#include "dsky_nv_consumer_vectors.h"
uint16_t dsky_nv_consumer_checkpoint(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){p66_bias_io io,old;agc_word channel11,oldchannel;enum dsky_nv_mission mission;uint16_t f,p,end,case_number,k,failures=0;uint8_t phase;if(n>=28u)return 1;case_number=dsky_nv_consumer_numbers[n];dsky_nv_consumer_input(s,&io,&channel11,case_number,&mission);*before=*s;old=io;oldchannel=channel11;for(phase=0;phase<dsky_nv_consumer_count(case_number);++phase){if(dsky_nv_consumer_step(s,&io,&channel11,mission,dsky_nv_consumer_stage_at(case_number,phase))!=P66_BIAS_OK)++failures;k=(uint16_t)(dsky_nv_consumer_sequence_offsets[n]+phase);p=dsky_nv_consumer_after_offsets[k];end=dsky_nv_consumer_after_offsets[k+1u];for(f=0;f<2051u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:f==2049u?old.interrupt_enabled:oldchannel;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:f==2049u?io.interrupt_enabled:channel11;if(p<end&&dsky_nv_consumer_after_patch[p][0]==f)expected=dsky_nv_consumer_after_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;}return failures;}
